{"id":"d26f9782-d825-4575-b891-9e53890f7218","type":"https://serlo.org/editor","variant":"serlo-org","domainOrigin":"serlo.org","version":2,"editorVersion":"0.22.0","dateModified":"2025-02-26T18:21:15.947Z","document":{"plugin":"exercise","state":{"content":{"plugin":"rows","state":[{"plugin":"text","state":[{"type":"p","children":[{"text":"Das Aufsprungprofil einer Skisprungschanze wird näherungsweise durch folgende Funktion beschrieben:"}]},{"type":"math","src":"f:x\mapsto\frac{48}{x^2+12}","inline":false,"children":[{"text":"f:x\mapsto\frac{48}{x^2+12}"}]},{"type":"p","children":[{"text":"Unter dem "K-Punkt" einer Sprungschanze versteht man  den Aufsprungpunkt mit der geringsten Aufsprungbelastung für den Springer."}]},{"type":"p","children":[{"text":"Berechne die horizontale Entfernung des K-Punktes vom Schanzentisch sowie den "},{"type":"a","href":"/1535","children":[{"text":"Neigungswinkel"}]},{"text":" der Aufsprungbahn im K-Punkt."}]}],"id":"a6f0c220-2f6c-49a9-a0d2-6732c21b9efe"},{"plugin":"image","state":{"src":"https://assets.serlo.org/legacy/57f7b5c18d3d4_c3dc0dd4569b980e486ec923ba100f9282cdb6a1.png","alt":"Kurvendiskussion Graph","caption":{"plugin":"text","state":[{"type":"p","children":[{}]}],"id":"f855c235-10ec-4f49-9b23-4d437538a093"}},"id":"5102800d-c3cd-4baf-9890-a29e4f522d82"},{"plugin":"text","state":[{"type":"p","children":[{"text":"Maßstab der Zeichnung: "},{"type":"math","src":"1\,LE = 50\,{m}","inline":true,"children":[{"text":"1\,LE = 50\,{m}"}]},{"text":""}]}],"id":"91b08697-5ee7-4a54-9fbf-d146adf225e4"}],"id":"030d436a-50f0-4ceb-8016-d17d29e67ebc"},"solution":{"plugin":"solution","state":{"prerequisite":{"id":"1577","title":"Kurvendiskussion"},"strategy":{"plugin":"text","state":[{"type":"p","children":[{}]}],"id":"eb778b3e-d029-490d-9dba-40dc90dcbac5"},"steps":{"plugin":"rows","state":[{"plugin":"text","state":[{"type":"p","children":[{"text":"Aus physikalischen Gründen ist der K-Punkt die steilste Stelle der Aufsprungbahn. Mathematisch ist demnach der "},{"type":"a","href":"/1653","children":[{"text":"Wendepunkt"}]},{"text":" der Funktion "},{"type":"math","src":" f","inline":true,"children":[{"text":"f"}]},{"text":" zu berechnen."}]}],"id":"4d34af52-e4a3-4002-91c7-e5b1e1f30efc"},{"plugin":"text","state":[{"type":"p","children":[{"text":"Bilde mithilfe der "},{"type":"a","href":"/1801","children":[{"text":"Quotientenrgel"}]},{"text":" die Ableitung von "},{"type":"math","src":"f","inline":true,"children":[{"text":"f"}]},{"text":": "}]},{"type":"math","src":"\begin{array}{rcl}
