f''(x) &=& -96 \cdot \dfrac{1 \cdot \left(x^2+12\right)^2-x\cdot2\left(x^2+12\right)\cdot 2x}{\left(x^2+12\right)^4} \\\\
&=& -96 \cdot \dfrac{\left(x^2+12\right)\left(x^2+12-4x^2\right)} {\left(x^2+12\right)^4} \\\\
&=& -96 \cdot\dfrac{12-3x^2}{\left(x^2+12\right)^3} \\\\
&=& 288 \cdot \dfrac{x^2-4}{\left(x^2+12\right)^3} 
\end{array}","inline":true,"children":[{"text":"\begin{align}f''(x) &= -96 \cdot \frac{1 \cdot \left(x^2+12\right)^2-x\cdot2\left(x^2+12\right)\cdot 2x}{\left(x^2+12\right)^4} \\&= -96 \cdot \frac{\left(x^2+12\right)\left(x^2+12-4x^2\right)} {\left(x^2+12\right)^4} \\&= -96 \cdot\frac{12-3x^2}{\left(x^2+12\right)^3} \\&=288 \cdot \frac{x^2-4}{\left(x^2+12\right)^3} \end{align}"}]},{"text":""}]}],"id":"9331e59b-4f24-4a25-9838-36165232dd67"},{"plugin":"rows","state":[{"plugin":"text","state":[{"type":"p","children":[{"text":"Setze nun die 2. Ableitung Null und bestätige den Vorzeichenwechsel der 2. Ableitung an ihrer Nullstelle und damit das Vorliegen eines Wendepunktes."}]}],"id":"109656b0-983a-41bb-8fba-a62f764df244"}],"id":"ad1ce73d-5314-4f0a-8a34-208573797b2f"},{"plugin":"rows","state":[{"plugin":"text","state":[{"type":"math","src":"\begin{array}{rcll} 288 \cdot\displaystyle\frac{x^2-4}{\left(x^2+12\right)^3} &= &0 &|:288 \cdot \left(x^2+12\right)^3 \\ x^2-4 &= &0 &|+4 \\x^2&= &4 &|\sqrt{} \\x&= &\pm2 \end{array}","inline":false,"children":[{"text":""}]}],"id":"b61556c3-5997-4ae4-92d8-584429c41a47"},{"plugin":"text","state":[{"type":"p","children":[{"text":"Beachte, dass "},{"type":"math","src":"f","inline":true,"children":[{"text":"f"}]},{"text":" nur für positive "},{"type":"math","src":"x","inline":true,"children":[{"text":"x"}]},{"text":" definiert ist."}]},{"type":"p","children":[{"text":""},{"type":"math","src":"f''(x)","inline":true,"children":[{"text":"f''(x)"}]},{"text":" besitzt für "},{"type":"math","src":"x=2","inline":true,"children":[{"text":"x=2"}]},{"text":" einen Vorzeichenwechsel, da gilt: "}]},{"type":"math","src":"f''(2 - h) < 0 \qquad\text{und}\qquad f''(2 + h) > 0","inline":false,"children":[{"text":""}]}],"id":"357af4cf-5dca-48cd-be48-ea35cf8d6cbb"}],"id":"f671a0a2-287d-4e10-bd87-23c0dc54e9b1"},{"plugin":"text","state":[{"type":"p","children":[{"text":"Erstes Teilergebnis:"}]},{"type":"p","children":[{"text":"Der K-Punkt ist also "},{"type"